2	/**
3	 * Marketing Agent Phase 1 — DISCOVERY SWEEP (worker task).
4	 *
5	 * Runs on the worker loop (hourly). For each ACTIVE MarketingSource it:
6	 *   1. Reads the public feed (Reddit public JSON / HN Algolia / RSS) — read-only.
7	 *   2. Dedupes by (sourceId, externalId) and stores NEW matches as MarketingSignal.
8	 *   3. For high-score NEW signals, generates a DISCLOSED draft reply via Claude
9	 *      and stores it as MarketingDraft (signal -> DRAFTED). If no Anthropic key
10	 *      is configured, it skips drafting gracefully and leaves the signal NEW with
11	 *      a note.
12	 *
13	 * CRITICAL: this sweep NEVER posts to any external platform. It only reads public
14	 * data and writes to our own DB. Every "post" in this system is a human action
15	 * recorded as a bookkeeping flag. See lib/marketing/discovery.ts + draft-gen.ts.
16	 */
17	
18	import { db } from "../lib/db";
19	import { getSettingBool, getSettingInt } from "../lib/settings";
20	import { discoverForSource } from "../lib/marketing/discovery";
21	import { generateDraft } from "../lib/marketing/draft-gen";
22	import { platformKeyConfigured } from "../lib/anthropic";
23	
24	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
25	
26	/** Max signals we auto-draft per sweep (bounds Anthropic spend + latency). */
27	const DRAFT_BUDGET_PER_SWEEP = 8;
28	
29	export async function marketingDiscoverySweep(): Promise<void> {
30	  // Operator kill-switch. Defaults ON, but a single Setting flip pauses discovery
31	  // without a deploy (matches the platform's other toggles).
32	  if (!(await getSettingBool("marketing_monitor_enabled", true))) return;
33	
34	  // Only draft for signals at/above this score — keeps the reviewer's queue high
35	  // signal and Anthropic usage low. Tunable from Settings.
36	  const draftThreshold = await getSettingInt("marketing_draft_threshold", 55);
37	
38	  let sources: { id: string; type: string; target: string; keywords: string[] }[] = [];
39	  try {
40	    sources = await db.marketingSource.findMany({ where: { active: true } });
41	  } catch {
42	    // Table not migrated yet (e.g. prod before `prisma db push`). No-op.
43	    return;
44	  }
45	  if (sources.length === 0) return;
46	
47	  let stored = 0;
48	  for (const source of sources) {
49	    let candidates;
50	    try {
51	      candidates = await discoverForSource(source);
52	    } catch (e) {
53	      console.error(`[marketing] discover error (${source.type}:${source.target})`, e);
54	      continue;
55	    }
56	    for (const c of candidates) {
57	      try {
58	        // Dedupe on the unique (sourceId, externalId): create only if new.
59	        const existing = await db.marketingSignal.findUnique({
60	          where: { sourceId_externalId: { sourceId: source.id, externalId: c.externalId } },
61	          select: { id: true },
62	        });
63	        if (existing) continue;
64	        await db.marketingSignal.create({
65	          data: {
66	            sourceId: source.id,
67	            externalId: c.externalId,
68	            url: c.url,
69	            title: c.title.slice(0, 300),
70	            excerpt: c.excerpt.slice(0, 1000),
71	            author: c.author.slice(0, 120),
72	            matchedKeywords: c.matchedKeywords,
73	            score: c.score,
74	            status: "NEW",
75	          },
76	        });
77	        stored++;
78	      } catch (e) {
79	        console.error("[marketing] signal store error", e);
80	      }
81	    }
82	    await sleep(1500); // pace between sources — polite, rate-limit friendly
83	  }
84	  if (stored > 0) console.log(`[marketing] stored ${stored} new signal(s)`);
85	
86	  await draftNewSignals(draftThreshold);
87	}
88	
89	/**
90	 * Draft disclosed replies for the top NEW signals. If no Anthropic key is set,
91	 * mark the signals with a note and leave them NEW (a human can draft manually).
92	 */
93	async function draftNewSignals(threshold: number): Promise<void> {
94	  let newSignals;
95	  try {
96	    newSignals = await db.marketingSignal.findMany({
97	      where: { status: "NEW", score: { gte: threshold } },
98	      orderBy: [{ score: "desc" }, { detectedAt: "desc" }],
99	      take: DRAFT_BUDGET_PER_SWEEP,
100	    });
101	  } catch {
102	    return;
103	  }
104	  if (newSignals.length === 0) return;
105	
106	  if (!platformKeyConfigured()) {
107	    // Skip gracefully — record why, once, so the UI can explain the queue is idle.
108	    for (const s of newSignals) {
109	      try {
110	        await db.marketingSignal.update({
111	          where: { id: s.id },
112	          data: { note: "No Anthropic key configured — draft manually or set ANTHROPIC_API_KEY." },
113	        });
114	      } catch {
115	        /* ignore */
116	      }
117	    }
118	    return;
119	  }
120	
121	  for (const s of newSignals) {
122	    try {
123	      const body = await generateDraft({
124	        title: s.title,
125	        excerpt: s.excerpt,
126	        url: s.url,
127	        matchedKeywords: s.matchedKeywords,
128	      });
129	      if (!body) {
130	        await db.marketingSignal.update({
131	          where: { id: s.id },
132	          data: { note: "Draft generation returned nothing (API error) — retry or draft manually." },
133	        });
134	        continue;
135	      }
136	      // Channel mirrors the source type where possible.
137	      const src = await db.marketingSource.findUnique({ where: { id: s.sourceId }, select: { type: true } });
138	      await db.marketingDraft.create({
139	        data: { signalId: s.id, body, channel: src?.type ?? "reddit", status: "DRAFT" },
140	      });
141	      await db.marketingSignal.update({
142	        where: { id: s.id },
143	        data: { status: "DRAFTED", note: "" },
144	      });
145	    } catch (e) {
146	      console.error("[marketing] draft error", e);
147	    }
148	  }
149	}
