209	// Customer per-server backup retention is now the backup TIER's keep count
210	// (lib/backup-tiers.ts): FREE keeps 2 (the historic default), PLUS keeps 7. Older
211	// archives are pruned after every successful backup so they never pile up.
212	// `resolveBackupKeep(tier, override)` is the single source; the paid Plus tier is
213	// the only thing that raises it above the old hardcoded 2.
214	
215	// Job types whose terminal failure genuinely leaves the VM in a bad/unknown
216	// run or disk state — only these should mark the server ERROR. Everything else
217	// (backup, snapshot-create, control-panel ops, SSL, migrate copy, game update…)
218	// is a side operation that doesn't touch the VM's run state.
219	//
220	// DISK_EXPAND is deliberately ABSENT: growing a disk never changes the VM's run
221	// state, so a failed expansion must leave the server RUNNING/STOPPED as it was.
222	// Its money is unwound by reconcileFailedJob instead.
223	const VM_STATE_FAILURE_JOBS = new Set<string>([
224	  "PROVISION", "REINSTALL", "DELETE", "RESIZE", "START", "STOP",
225	  "REBOOT", "SUSPEND", "UNSUSPEND", "BACKUP_RESTORE", "SNAPSHOT_ROLLBACK",
226	]);
