233	async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any; user: any }> {
234	  const server = await db.server.findUnique({
235	    where: { id: job.serverId! },
236	    // `user` (email) + `node` (publicIp) are needed for the deployment
237	    // confirmation email fired on provision success; the rest is used throughout.
238	    include: { plan: true, osTemplate: true, node: true, user: { select: { id: true, email: true } } },
239	  });
240	  if (!server) throw new Error(`Server ${job.serverId} not found`);
241	  return server as any;
242	}
