244	/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
245	async function nodeFor(server: any) {
246	  const n =
247	    server.node ??
248	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
249	    (await db.node.findFirst({ where: { enabled: true } }));
250	  if (!n) {
251	    // No Node rows yet — use the env-configured primary via the global client.
252	    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
253	  }
254	  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
255	}
