257	/** YAML-safe indent of a multi-line script under a `content: |` block. */
258	function indentBlock(text: string, spaces: number): string {
259	  const pad = " ".repeat(spaces);
260	  return text.split("\n").map((l) => pad + l).join("\n");
261	}
262	
263	/**
264	 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
265	 * plus any control-panel/app install script and selected add-ons. Long installs
266	 * run in the background so the VM reports ready promptly.
267	 */
268	function buildCloudInit(server: any): string {
269	  const addons = (server.addons ?? {}) as {
270	    malwareScanner?: boolean;
271	    dailyBackup?: boolean;
272	    docker?: boolean;
273	    claudeCode?: boolean;
274	  };
275	  const setup: string[] = [];
276	
277	  // Pre-bake Claude Code (Anthropic CLI) on every server unless explicitly opted
278	  // out. Customers SSH in and run `claude` using their own subscription or API
279	  // key — no setup on our side, zero token cost to us. Installs run in the
280	  // background (nohup below) so the VM still reports ready quickly.
281	  if (addons.claudeCode !== false) {
282	    // Same steps the backfill (task #73) runs on existing servers — one source of
283	    // truth in lib/claude-install.ts, so cloud-init and backfill never drift.
284	    setup.push(...CLAUDE_CLI_INSTALL_STEPS);
285	  }
286	
287	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
288	  if (addons.malwareScanner)
289	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
290	  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);
291	  // NxCloud: when this VM backs a managed Nextcloud instance, `provision` stashes
292	  // the per-instance install script here (admin creds injected). See worker/nxcloud.ts.
293	  if (server.__nxcloudSetup) setup.push(server.__nxcloudSetup);
294	
295	  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
296	
297	  // Every VM gets a swapfile. A small plan (the 2 GB Starter is the common one)
298	  // with ZERO swap OOM-kills under any spike — a container image build, a traffic
299	  // burst, a migrated app's first request — and the kernel kills a process with no
300	  // warning and nothing to fall back on. A RAM-sized swapfile (capped so it never
301	  // eats a small root disk) turns a hard kill into slow-but-alive. Idempotent:
302	  // skips if any swap is already on or /swapfile already exists.
303	  const swapScript = [
304	    "#!/bin/bash",
305	    "# Nxeon: ensure a swapfile exists as an OOM safety net on small-RAM VMs.",
306	    "if swapon --show=NAME --noheadings 2>/dev/null | grep -q .; then exit 0; fi",
307	    "[ -e /swapfile ] && exit 0",
308	    'MEM_MB=$(awk "/MemTotal/{print int(\\$2/1024)}" /proc/meminfo 2>/dev/null || echo 1024)',
309	    "SWAP_MB=$MEM_MB",
310	    '[ "$SWAP_MB" -lt 1024 ] && SWAP_MB=1024',
311	    '[ "$SWAP_MB" -gt 4096 ] && SWAP_MB=4096',
312	    "# Leave >2 GB free on / so the swapfile never fills the root disk.",
313	    'AVAIL_MB=$(df -Pm / | awk "NR==2{print \\$4}")',
314	    '[ -n "$AVAIL_MB" ] && [ "$AVAIL_MB" -lt $((SWAP_MB + 2048)) ] && SWAP_MB=$((AVAIL_MB - 2048))',
315	    '[ "$SWAP_MB" -lt 256 ] && exit 0',
316	    "fallocate -l ${SWAP_MB}M /swapfile 2>/dev/null || dd if=/dev/zero of=/swapfile bs=1M count=${SWAP_MB} 2>/dev/null || exit 0",
317	    "chmod 600 /swapfile",
318	    "mkswap /swapfile >/dev/null 2>&1 || exit 0",
319	    "swapon /swapfile 2>/dev/null || exit 0",
320	    "grep -q '^/swapfile ' /etc/fstab 2>/dev/null || echo '/swapfile none swap sw 0 0' >> /etc/fstab",
321	    "grep -q '^vm.swappiness' /etc/sysctl.conf 2>/dev/null || { echo 'vm.swappiness=10' >> /etc/sysctl.conf; sysctl -w vm.swappiness=10 >/dev/null 2>&1 || true; }",
322	  ].join("\n");
323	
324	  // A friendly first-login guide + MOTD banner pointing at the portal hub.
325	  const welcome = [
326	    "# Welcome to your Nxeon server",
327	    "",
328	    "## Build anything with Claude Code — it's already installed",
329	    "",
330	    "1. You're already logged in. Just run:",
331	    "",
332	    "   claude",
333	    "",
334	    "2. Sign in once — either with your Claude subscription (Pro/Max) or an",
335	    "   Anthropic API key. See the step-by-step guide with screenshots at:",
336	    "",
337	    "   https://nxeon.cloud/dashboard/claude-code",
338	    "",
339	    "3. Then describe what you want in plain English, for example:",
340	    '   "Build a modern website for my coffee shop with a menu and contact form,',
341	    '    then run it and tell me the URL to preview it."',
342	    "",
343	    "Copy-paste starter prompts (spa site, booking app, REST API, Discord bot,",
344	    "and 20+ more) and how-to guides live in your portal at the link above.",
345	    "",
346	    "Happy building!",
347	  ].join("\n");
348	
349	  // Honest MOTD: check for the binary at login and only claim it's installed when
350	  // it really is. A failed background install must never greet the customer with
351	  // "Claude Code is pre-installed" and then 'command not found' — it tells them how
352	  // to install it instead.
353	  const motd = [
354	    "#!/bin/sh",
355	    'if [ -t 1 ]; then',
356	    '  if command -v claude >/dev/null 2>&1 || [ -x /usr/local/bin/claude ]; then',
357	    '    printf "\\n  \\033[1mNxeon\\033[0m — Claude Code is pre-installed on this server.\\n"',
358	    '    printf "  Run \\033[1mclaude\\033[0m to start building. Guide: https://nxeon.cloud/dashboard/claude-code\\n"',
359	    "  else",
360	    '    printf "\\n  \\033[1mNxeon\\033[0m — install Claude Code:  curl -fsSL https://claude.ai/install.sh | bash\\n"',
361	    '    printf "  Then run \\033[1mclaude\\033[0m. Guide: https://nxeon.cloud/dashboard/claude-code\\n"',
362	    "  fi",
363	    '  printf "  Full walkthrough: \\033[2m~/START-WITH-CLAUDE.md\\033[0m\\n\\n"',
364	    "fi",
365	  ].join("\n");
366	
367	  return `#cloud-config
368	package_update: true
369	packages:
370	  - qemu-guest-agent
371	ssh_pwauth: true
372	disable_root: false
373	write_files:
374	  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
375	    permissions: "0644"
376	    content: |
377	      PermitRootLogin yes
378	      PasswordAuthentication yes
379	  - path: /root/START-WITH-CLAUDE.md
380	    permissions: "0644"
381	    content: |
382	${indentBlock(welcome, 6)}
383	  - path: /etc/profile.d/nxeon-welcome.sh
384	    permissions: "0755"
385	    content: |
386	${indentBlock(motd, 6)}
387	  - path: /root/nxeon-swap.sh
388	    permissions: "0755"
389	    content: |
390	${indentBlock(swapScript, 6)}
391	  - path: /root/nxeon-setup.sh
392	    permissions: "0755"
393	    content: |
394	${indentBlock(script, 6)}
395	runcmd:
396	  - systemctl enable --now qemu-guest-agent
397	  - systemctl restart ssh || systemctl restart sshd
398	  - /root/nxeon-swap.sh > /var/log/nxeon-swap.log 2>&1 || true
399	  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
400	`;
401	}
402	
403	const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
404	const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";
405	
406	/**
407	 * Allocate a vmid for a brand-new server, refusing any id that still owns backup
408	 * archives from a previous tenant (see `pickProvisionVmid` for the incident).
409	 *
410	 * If the archive listing cannot be read we do NOT silently fall back to the raw
411	 * `nextVmid()` — that is the exact behaviour that leaks a previous tenant's data,
412	 * and a provision that fails is recoverable while a cross-tenant disclosure is
413	 * not. The job retries; an operator sees why.
414	 */
415	async function allocateFreshVmid(conn: any): Promise<number> {
416	  const candidate = await conn.nextVmid();
417	  const archived = await archivedVmids(conn);
418	
419	  // Ids already in use, so skipping forward cannot land on a live VM. Read
420	  // cluster-wide (qemu + lxc); fall back to this node's qemu list.
421	  let taken = new Set<number>();
422	  try {
423	    const res: any[] = await conn.get("/cluster/resources", { type: "vm" });
424	    for (const r of res ?? []) if (Number.isInteger(r?.vmid)) taken.add(r.vmid);
425	  } catch {
426	    const vms: any[] = await conn.get(`/nodes/${conn.node}/qemu`);
427	    taken = new Set((vms ?? []).map((v: any) => Number(v?.vmid)).filter(Number.isInteger));
428	  }
429	
430	  const { vmid, skipped } = pickProvisionVmid({ candidate, takenVmids: taken, archivedVmids: archived });
431	  if (skipped.length > 0) {
432	    console.warn(
433	      `[worker] vmid ${skipped.join(", ")} skipped for provisioning — still holds backup archives ` +
434	        `from a previous server; allocated ${vmid} instead`
435	    );
436	  }
437	  return vmid;
438	}
439	
440	async function provision(job: Job) {
441	  const server = await loadServer(job);
442	  // Clear any stale failure reason from a previous attempt as this run starts, so
443	  // a successful retry doesn't leave the last error hanging around on the row.
444	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING", provisionError: null } });
445	
446	  if (SANDBOX) {
447	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
448	    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
449	    const vmid = server.vmid ?? (990000 + (await db.server.count()));
450	    const password = generatePassword();
451	    const ip = sandboxIp(vmid);
452	    await db.server.update({
453	      where: { id: server.id },
454	      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
455	    });
456	    await notify(
457	      server.userId,
458	      `Server ${server.hostname} is ready`,
459	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
460	      `/dashboard/servers/${server.id}`
461	    );
462	    // Post-purchase review request (once per server, skipped if no profiles set).
463	    await sendReviewRequestForServer(server.id);
464	    return;
465	  }
466	
467	  const { conn, row: nodeRow } = await nodeFor(server);
468	  const storage = server.plan.storageTier === "hdd"
469	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
470	    : nodeRow?.storageNvme ?? "vmdata";
471	
472	  // Pick a vmid that does NOT still own a previous tenant's backup archives.
473	  // `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
474	  // server's vzdump archives, so the id freed by a deletion comes back carrying
475	  // the old owner's backups — which every backup surface then attributes to the
