701	/**
702	 * Tear down a VM. Idempotent and verified — see `destroyVmIdempotent` in
703	 * lib/proxmox.ts for the incident and the ladder. The bare version of this
704	 * function threw on an already-absent VM, which is what made a retried REINSTALL
705	 * destroy a customer's server permanently.
706	 */
707	async function destroyVm(conn: any, vmid: number): Promise<DestroyOutcome> {
708	  const host: VmDestroyHost = {
709	    probe: async (id) => {
710	      try {
711	        await conn.vmStatus(id);
712	        return "present";
713	      } catch (e) {
714	        // Only a vmid-anchored "config does not exist" proves absence. Anything
715	        // else (auth, network, a locked node) is genuinely unknown and must not
716	        // be read as "already gone".
717	        return isVmAbsentError(e, id) ? "absent" : "unknown";
718	      }
719	    },
720	    stop: async (id) => {
721	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${id}/status/stop`, {});
722	      await conn.waitForTask(stopUpid);
723	    },
724	    destroy: async (id) => {
725	      const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, {
726	        "destroy-unreferenced-disks": 1,
727	        purge: 1,
728	      });
729	      await conn.waitForTask(delUpid, 600_000);
730	    },
731	  };
732	  return destroyVmIdempotent(host, vmid);
733	}
