735	async function remove(job: Job) {
736	  const server = await loadServer(job);
737	  const { conn } = await nodeFor(server);
738	  if (!SANDBOX && server.vmid) {
739	    // `destroyVm` is now idempotent and VERIFIES the VM is gone before returning,
740	    // so the absent case no longer needs to be caught here at all. The catch that
741	    // remains is narrowed to this vmid: it used to swallow any error containing
742	    // "does not exist", which also matches `storage 'vmdata' does not exist` and
743	    // `volume ... does not exist` — errors that mean the VM is very much still
744	    // running. On one of those the handler proceeded to delete the Server row and
745	    // every Volume row pinned to it, leaving a live VM with no database record:
746	    // invisible to billing, invisible to the panel, still holding the customer's
747	    // data and impossible to reach through any surface we own.
748	    try {
749	      await destroyVm(conn, server.vmid);
750	    } catch (e: any) {
751	      if (!isVmAbsentError(e, server.vmid)) throw e;
752	    }
753	    // Best-effort: remove the per-server cloud-init snippet
754	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
755	  }
756	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
757	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
758	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
759	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
760	  // diskName and keep billing forever. Remove them and notify the owner. (The
761	  // reinstall guard already blocks the accidental case; a full server delete is an
762	  // intentional teardown, so we drop the volumes with it.)
763	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
764	  if (orphanVolumes.length > 0) {
765	    await db.volume.deleteMany({ where: { serverId: server.id } });
766	    for (const v of orphanVolumes) {
767	      await notify(
768	        v.userId,
769	        `Volume "${v.name}" was removed`,
770	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
771	        "/dashboard/volumes",
772	      ).catch(() => {});
773	    }
774	  }
775	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
776	  // server.delete cascade removes THIS running Job row — the success-path
777	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
778	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
779	  await db.server.delete({ where: { id: server.id } });
780	  // Best-effort BY NECESSITY: the server row is gone, so a throw here re-queues
781	  // DELETE, which then dies on "Server not found" and the sync is never retried
782	  // (H5's aggravating factor). The failure is logged in full rather than hidden.
783	  if (!SANDBOX) await syncPortForwardsBestEffort(`delete ${server.hostname}`);
784	}
