786	async function reinstall(job: Job) {
787	  const server = await loadServer(job);
788	  if (SANDBOX) {
789	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
790	    await notify(
791	      server.userId,
792	      `Server ${server.hostname} reinstalled (sandbox)`,
793	      "The sandbox server was reinstalled (no real VM was touched).",
794	      `/dashboard/servers/${server.id}`
795	    );
796	    return;
797	  }
798	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
799	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
800	  // EVERY disk the vmid owns, including attached block-storage Volume disks
801	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
802	  // by that vmid, and both purge and the default destroy (which removes disks
803	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
804	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
805	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
806	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
807	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
808	  // can be re-attached after the reinstall. This runs BEFORE any status change or
809	  // destructive call, so a blocked reinstall touches nothing.
810	  //
811	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
812	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
813	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
814	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
815	  // let the worst path through: fill a volume, Detach (the UI says "Data is
816	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
817	  // Detaching is therefore NOT sufficient protection, and telling the customer to
818	  // detach was wrong advice; they must delete the volume (which destroys just
819	  // that disk, deliberately) or move it to another server first.
820	  const pinnedVolumes = await db.volume.findMany({
821	    where: { serverId: server.id },
822	  });
823	  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
824	  const realPinned = pinnedVolumes.filter(
825	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
826	  );
827	  if (realPinned.length > 0) {
828	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
829	    throw new Error(
830	      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
831	        `Reinstalling purges every disk this server owns — including detached volumes ` +
832	        `that are still assigned to it — and that cannot be undone.`
833	    );
834	  }
835	
836	  const { conn } = await nodeFor(server);
837	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
838	  if (server.vmid) await destroyVm(conn, server.vmid);
839	  await provision(job);
840	}
