// Cloudflare OAuth — "Connect Cloudflare" instead of pasting an API token.
//
// Plain server-side module (NO "use server") — imported by the OAuth routes, the
// server actions and the DNS helpers. Never bundled to the client; no token or
// secret is ever logged or returned to the browser.
//
// Nxeon is a server-side Next.js app, so we are a CONFIDENTIAL client: the
// Authorization Code flow with a client secret (client_secret_post), PLUS PKCE
// (S256) because Cloudflare advertises support for it and it costs us nothing.
// Cloudflare supports ONLY the authorization-code grant for third-party clients
// (no client-credentials / implicit / device), plus refresh_token for renewals.
//
// ---------------------------------------------------------------------------
// PROTOCOL CONSTANTS — the one block to correct if Cloudflare changes anything.
//
// CONFIRMED from Cloudflare docs + their live OIDC discovery document
// (https://dash.cloudflare.com/.well-known/openid-configuration, fetched
// 2026-07-25):
//   * authorize  https://dash.cloudflare.com/oauth2/auth
//   * token      https://dash.cloudflare.com/oauth2/token
//   * revoke     https://dash.cloudflare.com/oauth2/revoke
//   * grant_types_supported includes "authorization_code" and "refresh_token"
//   * token_endpoint_auth_methods_supported includes client_secret_post/basic
//   * code_challenge_methods_supported includes "S256"
//   * "offline_access" is a supported scope (that's what yields a refresh token)
//
// ASSUMED (could NOT be confirmed from public docs): the exact resource scope
// names for zone read + DNS edit. Cloudflare documents only that "OAuth scope
// names correspond to Cloudflare API token permission names" and that the full
// list is enumerable at `GET https://api.cloudflare.com/client/v4/oauth/scopes`
// — which requires an authenticated API token, so it can't be read from here.
// The API-token permissions we need are named "Zone Read" and "DNS Write"
// (Zone category), whose documented permission keys are `#zone:read` and
// `#dns_records:edit`; the default below is those minus the `#`, which is also
// the form Cloudflare's own first-party client (wrangler) sends (`zone:read`).
// If Cloudflare's client registration UI shows a different form (their docs
// example uses a dotted style, e.g. `workers-platform.read`), DO NOT edit code:
// set CLOUDFLARE_OAUTH_SCOPES in the env to the exact space-separated list
// shown when registering the client. Candidates, in order of likelihood:
//   1. "zone:read dns_records:edit offline_access"   (default below)
//   2. "zone.read dns.edit offline_access"
// We request the MINIMUM needed: read the customer's zones, write DNS records.
// ---------------------------------------------------------------------------

import { db } from "./db";
import { encryptSecret, decryptSecret } from "./crypto-box";
import { SANDBOX } from "./sandbox";
import { createHash, randomBytes } from "node:crypto";

export const CF_OAUTH_AUTHORIZE_URL =
  process.env.CLOUDFLARE_OAUTH_AUTHORIZE_URL ?? "https://dash.cloudflare.com/oauth2/auth";
export const CF_OAUTH_TOKEN_URL =
  process.env.CLOUDFLARE_OAUTH_TOKEN_URL ?? "https://dash.cloudflare.com/oauth2/token";
export const CF_OAUTH_REVOKE_URL =
  process.env.CLOUDFLARE_OAUTH_REVOKE_URL ?? "https://dash.cloudflare.com/oauth2/revoke";

/** Space-separated scope list sent to /authorize. Env-overridable (see above). */
export const CF_OAUTH_SCOPES =
  process.env.CLOUDFLARE_OAUTH_SCOPES ?? "zone:read dns_records:edit offline_access";

/** Human summary of the access we ask for, shown in the UI. */
export const CF_SCOPE_SUMMARY = "read your zones and edit DNS records";

/** Redirect URI — must be registered verbatim on the Cloudflare OAuth client. */
export function cfRedirectUri(): string {
  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
  return `${base}/api/integrations/cloudflare/callback`;
}

/**
 * Is the OAuth client registered in this environment? When false the UI hides
 * the "Connect Cloudflare" button and falls back to the paste-a-token path, so
 * nothing breaks before the owner registers the client in their dashboard.
 */
export function cloudflareOauthConfigured(): boolean {
  return Boolean(
    (process.env.CLOUDFLARE_OAUTH_CLIENT_ID ?? "").trim() &&
      (process.env.CLOUDFLARE_OAUTH_CLIENT_SECRET ?? "").trim(),
  );
}

// ---- Stored credentials ----------------------------------------------------

/**
 * OAuth credentials as stored (encrypted) in `User.cloudflareTokenEnc`.
 *
 * NO SCHEMA CHANGE: the existing column holds either
 *   - a JSON blob of this shape  → OAuth connection, or
 *   - a bare API-token string    → legacy pasted token (still fully supported).
 * `readStoredCloudflare` sniffs which one it is.
 */
export type CfOauthCreds = {
  accessToken: string;
  refreshToken?: string | null;
  /** Epoch ms when the access token expires (absent = unknown/never). */
  expiresAt?: number | null;
  scope?: string | null;
};

export type StoredCloudflare =
  | { kind: "oauth"; creds: CfOauthCreds }
  | { kind: "token"; token: string }
  | null;

/** Encrypt OAuth creds for storage in the existing column. */
export function packCreds(creds: CfOauthCreds): string {
  return encryptSecret(JSON.stringify({ v: 1, ...creds }));
}

/**
 * Decrypt + classify whatever is in `User.cloudflareTokenEnc`. A value that
 * parses as a JSON object with an accessToken is an OAuth connection; anything
 * else non-empty is treated as a legacy pasted API token.
 */
export function readStoredCloudflare(enc: string | null | undefined): StoredCloudflare {
  const raw = decryptSecret(enc);
  if (!raw) return null;
  const trimmed = raw.trim();
  if (trimmed.startsWith("{")) {
    try {
      const parsed = JSON.parse(trimmed) as Partial<CfOauthCreds>;
      if (parsed && typeof parsed.accessToken === "string" && parsed.accessToken) {
        return {
          kind: "oauth",
          creds: {
            accessToken: parsed.accessToken,
            refreshToken: parsed.refreshToken ?? null,
            expiresAt: typeof parsed.expiresAt === "number" ? parsed.expiresAt : null,
            scope: parsed.scope ?? null,
          },
        };
      }
    } catch {
      // Not JSON after all — fall through to the legacy-token branch.
    }
    return null;
  }
  return { kind: "token", token: trimmed };
}

// ---- Authorization request -------------------------------------------------

/** Random URL-safe string for `state` / the PKCE verifier. */
export function randomUrlSafe(bytes = 32): string {
  return randomBytes(bytes).toString("base64url");
}

/** S256 code challenge for a PKCE verifier. */
export function pkceChallenge(verifier: string): string {
  return createHash("sha256").update(verifier).digest("base64url");
}

/** Build the Cloudflare consent URL for this connection attempt. */
export function cfAuthorizeUrl(opts: { state: string; codeChallenge: string }): string {
  const url = new URL(CF_OAUTH_AUTHORIZE_URL);
  url.searchParams.set("response_type", "code");
  url.searchParams.set("client_id", (process.env.CLOUDFLARE_OAUTH_CLIENT_ID ?? "").trim());
  url.searchParams.set("redirect_uri", cfRedirectUri());
  // Cloudflare grants the permissions the OAuth CLIENT was registered with; it
  // does NOT accept them as requestable authorize-time scopes. Probing the live
  // endpoint returns `invalid_scope` — "The OAuth 2.0 Client is not allowed to
  // request scope 'X'" — for every value tried, including `offline_access` and
  // `openid`, while omitting the parameter entirely succeeds (302 to consent).
  // So send `scope` only if an operator explicitly sets CLOUDFLARE_OAUTH_SCOPES.
  if (CF_OAUTH_SCOPES.trim()) url.searchParams.set("scope", CF_OAUTH_SCOPES.trim());
  url.searchParams.set("state", opts.state);
  url.searchParams.set("code_challenge", opts.codeChallenge);
  url.searchParams.set("code_challenge_method", "S256");
  return url.toString();
}

// ---- Token endpoint --------------------------------------------------------

type TokenResponse = {
  access_token?: string;
  refresh_token?: string;
  expires_in?: number;
  scope?: string;
  token_type?: string;
  error?: string;
  error_description?: string;
};

/**
 * POST to the token endpoint with client_secret_post auth. Returns creds or a
 * short error string. NEVER includes the client secret or any token in the
 * error text (Cloudflare's `error_description` is safe — it describes the grant).
 */
async function tokenRequest(body: Record<string, string>): Promise<{ creds?: CfOauthCreds; error?: string }> {
  const clientId = (process.env.CLOUDFLARE_OAUTH_CLIENT_ID ?? "").trim();
  const clientSecret = (process.env.CLOUDFLARE_OAUTH_CLIENT_SECRET ?? "").trim();

  // Token-endpoint auth method must match how the OAuth client was REGISTERED in
  // the Cloudflare dashboard. Ours is registered as "Client Secret Basic", so we
  // send HTTP Basic by default; set CLOUDFLARE_OAUTH_TOKEN_AUTH=post to switch to
  // client_secret_post (credentials in the form body) without a code change.
  const useBasic = (process.env.CLOUDFLARE_OAUTH_TOKEN_AUTH ?? "basic").toLowerCase() !== "post";

  const params = new URLSearchParams({
    ...body,
    client_id: clientId,
    ...(useBasic ? {} : { client_secret: clientSecret }),
  });

  const headers: Record<string, string> = {
    "Content-Type": "application/x-www-form-urlencoded",
    Accept: "application/json",
  };
  if (useBasic) {
    // RFC 6749 §2.3.1 — client_id:client_secret, base64, in the Authorization header.
    headers.Authorization = `Basic ${Buffer.from(`${clientId}:${clientSecret}`).toString("base64")}`;
  }

  let res: Response;
  try {
    res = await fetch(CF_OAUTH_TOKEN_URL, {
      method: "POST",
      headers,
      body: params.toString(),
      cache: "no-store",
    });
  } catch {
    return { error: "Couldn't reach Cloudflare to finish connecting. Try again shortly." };
  }

  let parsed: TokenResponse | null = null;
  try {
    parsed = (await res.json()) as TokenResponse;
  } catch {
    parsed = null;
  }

  if (!res.ok || !parsed?.access_token) {
    const detail = parsed?.error_description || parsed?.error || `HTTP ${res.status}`;
    return { error: `Cloudflare rejected the connection (${String(detail).slice(0, 160)}).` };
  }

  const expiresIn = typeof parsed.expires_in === "number" ? parsed.expires_in : null;
  return {
    creds: {
      accessToken: parsed.access_token,
      refreshToken: parsed.refresh_token ?? null,
      expiresAt: expiresIn ? Date.now() + expiresIn * 1000 : null,
      scope: parsed.scope ?? CF_OAUTH_SCOPES,
    },
  };
}

/** Exchange an authorization code (with the PKCE verifier) for credentials. */
export async function cfExchangeCode(opts: {
  code: string;
  codeVerifier: string;
}): Promise<{ creds?: CfOauthCreds; error?: string }> {
  return tokenRequest({
    grant_type: "authorization_code",
    code: opts.code,
    redirect_uri: cfRedirectUri(),
    code_verifier: opts.codeVerifier,
  });
}

/** Trade a refresh token for a fresh access token. */
export async function cfRefresh(refreshToken: string): Promise<{ creds?: CfOauthCreds; error?: string }> {
  return tokenRequest({ grant_type: "refresh_token", refresh_token: refreshToken });
}

/**
 * Best-effort revoke at Cloudflare so disconnecting here also drops their side.
 * Never throws and never blocks the local disconnect.
 */
export async function cfRevoke(token: string): Promise<void> {
  if (SANDBOX || !cloudflareOauthConfigured()) return;
  try {
    await fetch(CF_OAUTH_REVOKE_URL, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        token,
        client_id: (process.env.CLOUDFLARE_OAUTH_CLIENT_ID ?? "").trim(),
        client_secret: (process.env.CLOUDFLARE_OAUTH_CLIENT_SECRET ?? "").trim(),
      }).toString(),
      cache: "no-store",
    });
  } catch {
    // Local disconnect is authoritative for us — ignore a failed remote revoke.
  }
}

// ---- The accessor every Cloudflare call goes through -----------------------

/** Friendly copy for the two "we can't act" states, reused by every surface. */
export const CF_NOT_CONNECTED =
  "Connect Cloudflare first — then we can create the DNS record for you. You can connect on this page or in Settings.";
export const CF_RECONNECT =
  "Your Cloudflare connection has expired. Reconnect Cloudflare in Settings and try again.";

/** Refresh a little early so a long request can't straddle the expiry. */
const REFRESH_SKEW_MS = 90_000;

/**
 * Resolve a usable bearer token for the Cloudflare v4 API from whatever the user
 * has connected. Handles both shapes:
 *   - legacy pasted API token → returned as-is (they don't expire on a clock),
 *   - OAuth creds → refreshed via the refresh token when expired/near-expiry,
 *     with the new blob re-encrypted back into `User.cloudflareTokenEnc`.
 *
 * Returns `{ error }` (never throws) for "nothing connected" and for a refresh
 * failure, so callers surface a friendly reconnect prompt instead of crashing.
 * `lib/cloudflare-dns.ts` keeps its per-call token signature — we just feed it
 * whatever this returns.
 */
export async function resolveCloudflareToken(user: {
  id: string;
  cloudflareTokenEnc: string | null;
}): Promise<{ token?: string; error?: string; needsReconnect?: boolean }> {
  const stored = readStoredCloudflare(user.cloudflareTokenEnc);
  if (!stored) return { error: CF_NOT_CONNECTED };
  if (stored.kind === "token") return { token: stored.token };

  const { creds } = stored;
  const expired =
    typeof creds.expiresAt === "number" && creds.expiresAt > 0
      ? Date.now() > creds.expiresAt - REFRESH_SKEW_MS
      : false;

  if (!expired) return { token: creds.accessToken };

  if (SANDBOX) {
    // Staging never contacts Cloudflare; keep the synthetic connection usable.
    return { token: creds.accessToken };
  }
  if (!creds.refreshToken) return { error: CF_RECONNECT, needsReconnect: true };

  const refreshed = await cfRefresh(creds.refreshToken);
  if (!refreshed.creds) {
    console.warn("[cloudflare-oauth] refresh failed for user", user.id);
    return { error: CF_RECONNECT, needsReconnect: true };
  }

  const merged: CfOauthCreds = {
    ...refreshed.creds,
    // Cloudflare may omit a rotated refresh token — keep the existing one then.
    refreshToken: refreshed.creds.refreshToken ?? creds.refreshToken,
  };
  await db.user
    .update({ where: { id: user.id }, data: { cloudflareTokenEnc: packCreds(merged) } })
    .catch(() => {
      // A failed persist is survivable: this request still uses the new token.
    });

  return { token: merged.accessToken };
}

