export async function saveColdEmailSettings(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const capRaw = Number(formData.get("coldemail_daily_cap"));
  const cap = Number.isFinite(capRaw) && capRaw > 0 ? Math.min(Math.floor(capRaw), 500) : 40;
  const basisRaw = String(formData.get("coldemail_default_consent_basis") ?? "LEGITIMATE_INTEREST");
  const basis = (CONSENT_BASES as readonly string[]).includes(basisRaw) ? basisRaw : "LEGITIMATE_INTEREST";
  const footer = String(formData.get("coldemail_footer_disclosure") ?? "").trim().slice(0, 600);

  // Phase 2 sending controls.
  const sendingEnabled = formData.get("cold_email_sending_enabled") === "on" || formData.get("cold_email_sending_enabled") === "true";
  const protectedDomains = String(formData.get("cold_email_protected_domains") ?? "").trim().slice(0, 600);
  const warmupEnabled = formData.get("coldemail_warmup_enabled") === "on" || formData.get("coldemail_warmup_enabled") === "true";
  const ceilingRaw = Number(formData.get("coldemail_warmup_ceiling"));
  const ceiling = Number.isFinite(ceilingRaw) && ceilingRaw > 0 ? Math.min(Math.floor(ceilingRaw), 500) : 40;
  const thresholdRaw = Number(formData.get("coldemail_complaint_threshold"));
  const threshold = Number.isFinite(thresholdRaw) && thresholdRaw > 0 ? Math.min(thresholdRaw, 1) : 0.003;

  await setSetting("coldemail_daily_cap", String(cap));
  await setSetting("coldemail_default_consent_basis", basis);
  await setSetting("coldemail_footer_disclosure", footer);
  await setSetting("cold_email_sending_enabled", sendingEnabled ? "true" : "false");
  await setSetting("cold_email_protected_domains", protectedDomains);
  await setSetting("coldemail_warmup_enabled", warmupEnabled ? "true" : "false");
  await setSetting("coldemail_warmup_ceiling", String(ceiling));
  await setSetting("coldemail_complaint_threshold", String(threshold));

  // Phase 3 burn thresholds (fractions, 0–1). Blank → keep the current/default.
  const frac = (key: string, fallback: number) => {
    const n = Number(formData.get(key));
    return Number.isFinite(n) && n > 0 && n <= 1 ? n : fallback;
  };
  await setSetting("coldemail_bounce_pause_inbox", String(frac("coldemail_bounce_pause_inbox", 0.018)));
  await setSetting("coldemail_bounce_pause_domain", String(frac("coldemail_bounce_pause_domain", 0.02)));
  await setSetting("coldemail_bounce_hard_stop", String(frac("coldemail_bounce_hard_stop", 0.05)));
  await setSetting("coldemail_complaint_pause_domain", String(frac("coldemail_complaint_pause_domain", 0.0008)));

  if (sendingEnabled) {
    await logEvent("warn", "coldemail.sending.enabled", { by: "admin" });
  }

  revalidatePath("/admin/coldemail/settings");
  revalidatePath("/admin/coldemail");
  return { ok: true };
}

