/// Singleton row (at most one) holding the platform's Google Search Console
/// OAuth connection. `refreshTokenEnc` is encrypted via lib/crypto-box
/// (encryptSecret/decryptSecret) — same pattern as Inbox.smtpPassEnc/imapPassEnc.
/// A dedicated table (not the general `Setting` store) because a refresh token
/// is a secret that needs real encryption-at-rest, not a plain key/value row.
model GscConnection {
  id              String   @id @default(cuid())
  refreshTokenEnc String // encryptSecret(...) — never plaintext
  accountEmail    String // the connected Google account, shown in the admin UI
  // The exact verified Search Console property string returned by sites.list,
  // e.g. "sc-domain:nxeon.cloud" or "https://nxeon.cloud/". Discovered once at
  // connect time rather than guessed — see resolveSiteUrl() in searchConsole.ts.
  siteUrl         String   @default("")
  connectedAt     DateTime @default(now())
  lastSyncAt      DateTime?
  updatedAt       DateTime @updatedAt
}

enum SeoOpportunityStatus {
  NEW
  REVIEWED
  ACTIONED
  DISMISSED
}

/// A "striking distance" SEO opportunity: a query where nxeon.cloud already
/// gets meaningful impressions but ranks outside the top 10 — demonstrated
/// interest with no page winning it yet. Upserted by the weekly sweep
/// (worker/seo.ts): re-running it updates the metrics + lastSeenAt on the
/// existing row rather than duplicating. `page` is nullable per the raw GSC
/// shape (a row lacks it only if a future sweep ever groups by query alone;
/// today's query+page grouping always supplies one), so a NEW row is only ever
/// unique per (query, page) pair.
model SeoOpportunity {
  id          String               @id @default(cuid())
  query       String
  page        String? // the currently-ranking URL, if GSC reports one
  impressions Int                  @default(0)
  clicks      Int                  @default(0)
  ctr         Float                @default(0)
  position    Float                @default(0)
  status      SeoOpportunityStatus @default(NEW)
  firstSeenAt DateTime             @default(now())
  lastSeenAt  DateTime             @default(now())
  createdAt   DateTime             @default(now())
  updatedAt   DateTime             @updatedAt

  @@unique([query, page])
  @@index([status])
  @@index([position])
  @@index([impressions])
}

