/**
 * Marketing Agent Phase 1 — DISCOVERY (read-only, rate-limited).
 *
 * Fetches candidate public posts from a MarketingSource and returns normalised
 * candidates. It ONLY reads public endpoints — no auth required, no writes, and
 * NOTHING is ever posted anywhere. The caller (worker/marketing.ts) dedupes and
 * stores matches as MarketingSignal rows; a human later reviews the drafts.
 *
 * Sources:
 *  - reddit:      public JSON search (no OAuth needed for low-volume read). A
 *                 REDDIT_CLIENT_ID/REDDIT_CLIENT_SECRET pair can be plugged in
 *                 later for higher, more reliable rate limits (see redditToken()).
 *  - hackernews:  the free Algolia API (no auth).
 *  - rss:         a plain feed fetch (best-effort XML item scrape).
 *
 * Keyword matching + scoring reuse the pure helpers in ./community-monitor so we
 * do not maintain a second scoring engine.
 */

import { scoreRelevance } from "./community-monitor";

/** Descriptive UA so Reddit/HN can identify us — polite, low-volume public read. */
const USER_AGENT =
  "web:nxeon-marketing-monitor:1.0 (read-only community monitor; contact admin@nxeon.com)";

/** A normalised discovery candidate before it becomes a MarketingSignal. */
export type Candidate = {
  externalId: string;
  url: string;
  title: string;
  excerpt: string;
  author: string;
  matchedKeywords: string[];
  score: number;
  createdUtc: number; // epoch seconds, for recency scoring
};

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** Which keywords appear in the text (case-insensitive substring match). */
function matchKeywords(text: string, keywords: readonly string[]): string[] {
  const hay = (text || "").toLowerCase();
  return keywords.filter((kw) => kw && hay.includes(kw.toLowerCase()));
}

/**
 * Recency bonus: fresh threads are worth replying to; a two-week-old thread is
 * mostly dead. Returns 0–10 added on top of the keyword relevance score.
 */
function recencyBonus(createdUtc: number): number {
  if (!createdUtc) return 0;
  const ageHours = (Date.now() / 1000 - createdUtc) / 3600;
  if (ageHours < 0) return 0;
  if (ageHours <= 24) return 10;
  if (ageHours <= 72) return 6;
  if (ageHours <= 24 * 7) return 3;
  return 0;
}

/** Combine keyword relevance (0–100) with a small recency bonus, capped at 100. */

