/**
 * Google Search Console — read-only OAuth integration.
 *
 * Powers "SEO Opportunity Discovery" (striking-distance queries: real search
 * volume, ranking outside the top 10, no page winning it yet). This module
 * NEVER writes to Google — it only reads via the `webmasters.readonly` scope
 * (searchanalytics.query + sites.list) and exchanges/refreshes OAuth tokens.
 * Findings are written only to our own DB, by worker/seo.ts.
 *
 * No `googleapis` package — it isn't installed and isn't worth adding for one
 * API surface. Plain `fetch` against Google's documented REST endpoints.
 *
 * Credentials come from env (GSC_OAUTH_CLIENT_ID / GSC_OAUTH_CLIENT_SECRET /
 * GSC_OAUTH_REDIRECT_URI), same as every other OAuth client in this codebase
 * (see lib/cloudflare-oauth.ts) — provisioned once in /etc/nxeon and copied
 * into each environment's own .env (prod keeps the nxeon.cloud redirect URI,
 * staging carries its own staging.nxeon.cloud one). Never hardcode either URI.
 *
 * This is a PLATFORM-WIDE singleton connection (one Search Console account for
 * the whole site), not a per-customer one — see `GscConnection` in the Prisma
 * schema, gated behind the "platform" admin area (ADMIN role only).
 */

import { db } from "../db";
import { encryptSecret, decryptSecret } from "../crypto-box";

const OAUTH_AUTHORIZE_URL = "https://accounts.google.com/o/oauth2/v2/auth";
const OAUTH_TOKEN_URL = "https://oauth2.googleapis.com/token";
const USERINFO_URL = "https://openidconnect.googleapis.com/v1/userinfo";
const SC_API_BASE = "https://www.googleapis.com/webmasters/v3";

/**
 * Scope requested at consent. `webmasters.readonly` is the scope the OAuth
 * client is actually published/reviewed for (non-sensitive, no verification
 * needed) — it is the ONLY scope that unlocks the Search Console API calls
 * below. `email` (a basic, non-sensitive identity scope every Google OAuth
 * client may request without extra consent-screen configuration) is added
 * alongside it purely so the callback can show "Connected as {email}" in the
 * admin UI; it grants no extra access to anything else and nothing here reads
 * profile/name data. If a live test ever shows Google rejecting the combined
 * scope, drop " email" and the connection still works — accountEmail just
 * falls back to a placeholder (see fetchAccountEmail below).
 */
const SCOPE = "https://www.googleapis.com/auth/webmasters.readonly email";

function clientId(): string {
  return (process.env.GSC_OAUTH_CLIENT_ID ?? "").trim();
}
function clientSecret(): string {
  return (process.env.GSC_OAUTH_CLIENT_SECRET ?? "").trim();
}
function redirectUri(): string {
  return (process.env.GSC_OAUTH_REDIRECT_URI ?? "").trim();
}

/** Is the OAuth client configured in this environment? Gates the UI's Connect button. */
export function gscConfigured(): boolean {
  return Boolean(clientId() && clientSecret() && redirectUri());
}

// ---------------------------------------------------------------------------
// Step 1: consent URL
// ---------------------------------------------------------------------------

/**
 * Build the Google OAuth consent URL. `access_type=offline` + `prompt=consent`
 * are both required to get a REFRESH token back (not just a short-lived access
 * token) — omitting either one means Google may silently skip issuing one on a
 * repeat consent.
 */
export function gscAuthorizeUrl(state: string): string {
  const url = new URL(OAUTH_AUTHORIZE_URL);
  url.searchParams.set("response_type", "code");
  url.searchParams.set("client_id", clientId());
  url.searchParams.set("redirect_uri", redirectUri());
  url.searchParams.set("scope", SCOPE);
  url.searchParams.set("access_type", "offline");
  url.searchParams.set("prompt", "consent");
  url.searchParams.set("state", state);
  return url.toString();
}

// ---------------------------------------------------------------------------
// Step 2/3: token endpoint (exchange + refresh)
// ---------------------------------------------------------------------------

type TokenResponse = {
  access_token?: string;
  refresh_token?: string;
  expires_in?: number;
  scope?: string;
  token_type?: string;
  error?: string;
  error_description?: string;
};

async function tokenRequest(params: Record<string, string>): Promise<{ token?: TokenResponse; error?: string }> {
  let res: Response;
  try {
    res = await fetch(OAUTH_TOKEN_URL, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
      body: new URLSearchParams({
        ...params,
        client_id: clientId(),
        client_secret: clientSecret(),
      }).toString(),
      cache: "no-store",
    });
  } catch {
    return { error: "Couldn't reach Google to finish connecting. Try again shortly." };
  }
  let parsed: TokenResponse | null = null;
  try {
    parsed = (await res.json()) as TokenResponse;
  } catch {
    parsed = null;
  }
  if (!res.ok || !parsed?.access_token) {
    const detail = parsed?.error_description || parsed?.error || `HTTP ${res.status}`;
    return { error: `Google rejected the connection (${String(detail).slice(0, 160)}).` };
  }
  return { token: parsed };
}

/** Exchange an authorization code for tokens. Returns the refresh token IF Google issued one. */
export async function gscExchangeCode(
  code: string,
): Promise<{ accessToken?: string; refreshToken?: string; error?: string }> {
  const { token, error } = await tokenRequest({
    grant_type: "authorization_code",
    code,
    redirect_uri: redirectUri(),
  });
  if (!token) return { error };
  return { accessToken: token.access_token, refreshToken: token.refresh_token };
}

/** Trade a stored refresh token for a fresh access token. */
export async function gscRefreshAccessToken(refreshToken: string): Promise<{ accessToken?: string; error?: string }> {
  const { token, error } = await tokenRequest({
    grant_type: "refresh_token",
    refresh_token: refreshToken,
  });
  if (!token) return { error };
  return { accessToken: token.access_token };
}

/**
 * Best-effort connected-account email, for display only ("Connected as …").
 * Never blocks storing the connection — a failure here (e.g. the `email`
 * scope wasn't actually granted) just falls back to a generic label.
 */
export async function gscFetchAccountEmail(accessToken: string): Promise<string | null> {
  try {
    const res = await fetch(USERINFO_URL, {
      headers: { Authorization: `Bearer ${accessToken}` },
      cache: "no-store",
    });
    if (!res.ok) return null;
    const data = (await res.json()) as { email?: string };
    return data.email ?? null;
  } catch {
    return null;
  }
}

// ---------------------------------------------------------------------------
// Search Console REST calls
// ---------------------------------------------------------------------------

export type GscSiteEntry = { siteUrl: string; permissionLevel: string };

/**
 * List every Search Console property this account can see. The reliable way
 * to learn whether nxeon.cloud is verified as a DOMAIN property
 * (`sc-domain:nxeon.cloud`) or a URL-PREFIX property (`https://nxeon.cloud/`)
 * — guessing the siteUrl path segment and getting the encoding wrong is the
 * most common way this API 404s.
 */
export async function gscListSites(accessToken: string): Promise<{ sites?: GscSiteEntry[]; error?: string }> {
  let res: Response;
  try {
    res = await fetch(`${SC_API_BASE}/sites`, {
      headers: { Authorization: `Bearer ${accessToken}` },
      cache: "no-store",
    });
  } catch {
    return { error: "Couldn't reach the Search Console API." };
  }
  if (!res.ok) {
    const body = await res.text().catch(() => "");
    return { error: `Search Console sites.list failed (HTTP ${res.status}): ${body.slice(0, 200)}` };
  }
  const data = (await res.json().catch(() => null)) as { siteEntry?: GscSiteEntry[] } | null;
  return { sites: data?.siteEntry ?? [] };
}

/**
 * Pick the verified property for our own domain out of a sites.list response.
 * Prefers the domain property (covers http/https + all subdomains) over a
 * URL-prefix property, since that's the stronger verification Search Console
 * offers; falls back to any entry that mentions the apex domain.
 */
export function resolveSiteUrl(sites: GscSiteEntry[], apexDomain = "nxeon.cloud"): string | null {
  const verified = sites.filter((s) => s.permissionLevel && s.permissionLevel !== "siteUnverifiedUser");
  const domainProp = verified.find((s) => s.siteUrl === `sc-domain:${apexDomain}`);
  if (domainProp) return domainProp.siteUrl;
  const prefixProp = verified.find((s) => s.siteUrl.includes(apexDomain));
  if (prefixProp) return prefixProp.siteUrl;
  // No verified match — fall back to ANY entry mentioning the domain, in case
  // permissionLevel comes back in a shape we didn't anticipate.
  return sites.find((s) => s.siteUrl.includes(apexDomain))?.siteUrl ?? null;
}

export type GscAnalyticsRow = {
  query: string;
  page: string | null;
  clicks: number;
  impressions: number;
  ctr: number;
  position: number;
};

/**
 * Query searchanalytics for the given site, grouped by query + page, over the
 * last `days` days (default 90). `siteUrl` MUST be the exact verified property
 * string from sites.list (URL-encoded in the path) — see resolveSiteUrl above.
 */
export async function gscQuerySearchAnalytics(opts: {
  accessToken: string;
  siteUrl: string;
  days?: number;
  rowLimit?: number;
}): Promise<{ rows?: GscAnalyticsRow[]; error?: string }> {
  const days = opts.days ?? 90;
  const rowLimit = opts.rowLimit ?? 5000;
  const end = new Date();
  const start = new Date(end.getTime() - days * 24 * 60 * 60 * 1000);
  const fmt = (d: Date) => d.toISOString().slice(0, 10);

  const endpoint = `${SC_API_BASE}/sites/${encodeURIComponent(opts.siteUrl)}/searchAnalytics/query`;
  let res: Response;
  try {
    res = await fetch(endpoint, {
      method: "POST",
      headers: { Authorization: `Bearer ${opts.accessToken}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        startDate: fmt(start),
        endDate: fmt(end),
        dimensions: ["query", "page"],
        rowLimit,
      }),
      cache: "no-store",
    });
  } catch {
    return { error: "Couldn't reach the Search Console API." };
  }
  if (!res.ok) {
    const body = await res.text().catch(() => "");
    return { error: `searchAnalytics.query failed (HTTP ${res.status}): ${body.slice(0, 200)}` };
  }
  const data = (await res.json().catch(() => null)) as {
    rows?: { keys?: string[]; clicks?: number; impressions?: number; ctr?: number; position?: number }[];
  } | null;
  const rows: GscAnalyticsRow[] = (data?.rows ?? []).map((r) => ({
    query: r.keys?.[0] ?? "",
    page: r.keys?.[1] ?? null,
    clicks: r.clicks ?? 0,
    impressions: r.impressions ?? 0,
    ctr: r.ctr ?? 0,
    position: r.position ?? 0,
  }));
  return { rows };
}

// ---------------------------------------------------------------------------
// GscConnection — the singleton DB row (encrypted refresh token)
// ---------------------------------------------------------------------------

export type GscConnectionStatus = {
  connected: boolean;
  accountEmail: string | null;
  siteUrl: string | null;
  connectedAt: Date | null;
  lastSyncAt: Date | null;
};

/** Read the connection row (there is at most one). Never returns the secret. */
export async function getGscConnectionStatus(): Promise<GscConnectionStatus> {
  const row = await db.gscConnection.findFirst({ orderBy: { connectedAt: "desc" } });
  if (!row) return { connected: false, accountEmail: null, siteUrl: null, connectedAt: null, lastSyncAt: null };
  return {
    connected: true,
    accountEmail: row.accountEmail || null,
    siteUrl: row.siteUrl || null,
    connectedAt: row.connectedAt,
    lastSyncAt: row.lastSyncAt,
  };
}

/**
 * Persist a new connection (encrypting the refresh token) — replaces any prior
 * row, since this is a one-connection-for-the-platform singleton. Also
 * resolves + stores the verified siteUrl right away via sites.list, so the
 * admin UI can show it immediately rather than waiting for the first sweep.
 */
export async function storeGscConnection(opts: { refreshToken: string; accessToken: string }): Promise<void> {
  const [accountEmail, sitesResult] = await Promise.all([
    gscFetchAccountEmail(opts.accessToken),
    gscListSites(opts.accessToken),
  ]);
  const siteUrl = sitesResult.sites ? resolveSiteUrl(sitesResult.sites) : null;

  await db.gscConnection.deleteMany({});
  await db.gscConnection.create({
    data: {
      refreshTokenEnc: encryptSecret(opts.refreshToken),
      accountEmail: accountEmail ?? "connected Google account",
      siteUrl: siteUrl ?? "",
    },
  });
}

/** Drop the connection. The next sweep tick then no-ops (see worker/seo.ts). */
export async function disconnectGsc(): Promise<void> {
  await db.gscConnection.deleteMany({});
}

/**
 * Resolve a fresh access token + the verified siteUrl for the stored
 * connection, refreshing via the encrypted refresh token. Never throws —
 * callers (the admin "sync now" action, the sweep) get `{ error }` instead so
 * they can surface a friendly message rather than crashing.
 */
export async function resolveGscAccessToken(): Promise<{
  accessToken?: string;
  siteUrl?: string;
  error?: string;
}> {
  const row = await db.gscConnection.findFirst({ orderBy: { connectedAt: "desc" } });
  if (!row) return { error: "Google Search Console isn't connected." };
  const refreshToken = decryptSecret(row.refreshTokenEnc);
  if (!refreshToken) return { error: "Stored connection is unreadable — reconnect Google Search Console." };

  const { accessToken, error } = await gscRefreshAccessToken(refreshToken);
  if (!accessToken) return { error: error ?? "Couldn't refresh the Google connection — reconnect it." };

  let siteUrl = row.siteUrl || null;
  if (!siteUrl) {
    // First refresh after a connection that couldn't resolve a site at connect
    // time (e.g. sites.list hiccuped) — try again now rather than staying blank.
    const sitesResult = await gscListSites(accessToken);
    siteUrl = sitesResult.sites ? resolveSiteUrl(sitesResult.sites) : null;
    if (siteUrl) {
      await db.gscConnection.update({ where: { id: row.id }, data: { siteUrl } }).catch(() => {});
    }
  }
  if (!siteUrl) {
    return { error: "No verified nxeon.cloud property found on this Google Search Console account." };
  }
  return { accessToken, siteUrl };
}

/** Mark a successful sync (used by the sweep after a clean run). */
export async function markGscSynced(): Promise<void> {
  await db.gscConnection.updateMany({ data: { lastSyncAt: new Date() } });
}

/**
 * SEO Opportunity Discovery — pure filtering logic over Google Search Console
 * data (read-only, rate-limited to one call per sweep). Mirrors the shape of
 * lib/marketing/discovery.ts: this module only fetches + filters; the caller
 * (worker/seo.ts) owns dedupe/upsert into our own DB.
 */

import { gscQuerySearchAnalytics, type GscAnalyticsRow } from "./searchConsole";

export type StrikingDistanceOpportunity = GscAnalyticsRow;

/** Default "content gap, worth a look" ranking band — see filterStrikingDistance. */
export const DEFAULT_MIN_POSITION = 11;
export const DEFAULT_MAX_POSITION = 30;

/**
 * Filter raw searchAnalytics rows down to "striking distance" candidates:
 * demonstrated interest (impressions at/above the tunable threshold) but
 * ranking outside the top 10. Position 11–30 is the realistic "content gap,
 * worth a look" zone (task spec) — deep enough to be a real near-miss, not so
 * deep that ranking movement is implausible. Deliberately NOT trying to judge
 * whether a good page already exists for the query — that classification is a
 * human call in v1; this just surfaces the raw candidates well.
 */
export function filterStrikingDistance(
  rows: GscAnalyticsRow[],
  opts: { minImpressions: number; minPosition?: number; maxPosition?: number },
): StrikingDistanceOpportunity[] {
  const minPosition = opts.minPosition ?? DEFAULT_MIN_POSITION;
  const maxPosition = opts.maxPosition ?? DEFAULT_MAX_POSITION;
  return rows.filter(
    (r) => r.impressions >= opts.minImpressions && r.position >= minPosition && r.position <= maxPosition,
  );
}

/** Fetch the lookback window from Search Console and filter it in one call. */
export async function fetchStrikingDistanceOpportunities(opts: {
  accessToken: string;
  siteUrl: string;
  lookbackDays: number;
  minImpressions: number;
}): Promise<{ opportunities?: StrikingDistanceOpportunity[]; error?: string }> {
  const { rows, error } = await gscQuerySearchAnalytics({
    accessToken: opts.accessToken,
    siteUrl: opts.siteUrl,
    days: opts.lookbackDays,
  });
  if (!rows) return { error };
  return { opportunities: filterStrikingDistance(rows, { minImpressions: opts.minImpressions }) };
}

/**
 * SEO Opportunity Discovery — DISCOVERY SWEEP (worker task, weekly).
 *
 * For the connected Google Search Console property it:
 *   1. Refreshes an access token from the stored (encrypted) refresh token.
 *   2. Pulls the last ~90 days of query+page data — read-only, one API call.
 *   3. Filters to real search volume (impressions >= a tunable threshold)
 *      ranking outside the top 10 (11–30 — the realistic content-gap zone).
 *   4. Upserts the result into SeoOpportunity — a re-run UPDATES the existing
 *      row's metrics + lastSeenAt rather than duplicating it.
 *
 * CRITICAL: this sweep NEVER writes to Google. It only calls the authorized
 * read-only Search Console API and writes to our own DB. A human reviews the
 * list at /admin/seo and marks rows REVIEWED/ACTIONED/DISMISSED themselves.
 * See lib/seo/searchConsole.ts (OAuth + API) and lib/seo/opportunities.ts
 * (filtering) — this file is the thin wrapper that ties them to the DB,
 * mirroring worker/marketing.ts over lib/marketing/discovery.ts.
 */

import { db } from "../lib/db";
import { getSettingBool, getSettingInt } from "../lib/settings";
import { resolveGscAccessToken, markGscSynced } from "../lib/seo/searchConsole";
import { fetchStrikingDistanceOpportunities } from "../lib/seo/opportunities";

export async function seoOpportunitySweep(): Promise<void> {
  // Operator kill-switch. Defaults ON: this sweep only ever reads Google's
  // authorized read-only API (webmasters.readonly) and writes to our own DB —
  // the same read-only/low-risk class as marketing_monitor_enabled, which also
  // defaults ON. A single Setting flip pauses it without a deploy. It is also
  // a natural no-op until an admin actually connects Search Console.
  if (!(await getSettingBool("seo_monitor_enabled", true))) return;

  // Tunable from Settings (see lib/actions-seo.ts / /admin/seo/settings).
  const lookbackDays = await getSettingInt("seo_lookback_days", 90);
  const minImpressions = await getSettingInt("seo_min_impressions", 15);

  let accessToken: string | undefined;
  let siteUrl: string | undefined;
  try {
    const resolved = await resolveGscAccessToken();
    accessToken = resolved.accessToken;
    siteUrl = resolved.siteUrl;
    if (!accessToken || !siteUrl) {
      // Not connected yet is the common/expected case — stay quiet. Anything
      // else (a stale connection, a resolvable-but-erroring site lookup) is
      // worth a log line so an admin investigating a stalled sweep can see it.
      if (resolved.error && !/isn't connected/i.test(resolved.error)) {
        console.error(`[seo] ${resolved.error}`);
      }
      return;
    }
  } catch (e) {
    console.error("[seo] token resolve error", e);
    return;
  }

  let opportunities;
  try {
    const result = await fetchStrikingDistanceOpportunities({ accessToken, siteUrl, lookbackDays, minImpressions });
    opportunities = result.opportunities;
    if (!opportunities) {
      console.error(`[seo] searchAnalytics query failed: ${result.error}`);
      return;
    }
  } catch (e) {
    console.error("[seo] searchAnalytics query error", e);
    return;
  }

  const now = new Date();
  let upserted = 0;
  for (const o of opportunities) {
    try {
      await db.seoOpportunity.upsert({
        where: { query_page: { query: o.query, page: o.page } },
        update: {
          impressions: o.impressions,
          clicks: o.clicks,
          ctr: o.ctr,
          position: o.position,
          lastSeenAt: now,
        },
        create: {
          query: o.query,
          page: o.page,
          impressions: o.impressions,
          clicks: o.clicks,
          ctr: o.ctr,
          position: o.position,
          firstSeenAt: now,
          lastSeenAt: now,
        },
      });
      upserted++;
    } catch (e) {
      console.error("[seo] opportunity upsert error", e);
    }
  }

  await markGscSynced().catch(() => {});
  if (upserted > 0) {
    console.log(`[seo] upserted ${upserted} striking-distance opportunit${upserted === 1 ? "y" : "ies"}`);
  }
}

