import { NextRequest, NextResponse } from "next/server";
import { realUser } from "@/lib/auth";
import { canAccess } from "@/lib/rbac";
import { gscAuthorizeUrl, gscConfigured } from "@/lib/seo/searchConsole";
import { randomBytes } from "node:crypto";

export const dynamic = "force-dynamic";

const base = () => (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");

/**
 * Step 1 of "Connect Google Search Console": start the Authorization Code
 * flow. ADMIN-only (platform area) — this is a platform-wide singleton
 * connection, not a per-customer one.
 *
 * Mints a CSRF `state`, stashes it in a short-lived httpOnly cookie, then
 * redirects to Google's consent screen. Nothing sensitive rides in the URL.
 */
export async function GET(_req: NextRequest) {
  const user = await realUser();
  if (!user || !canAccess(user.role, "platform")) {
    return NextResponse.redirect(`${base()}/admin`);
  }

  if (!gscConfigured()) {
    return NextResponse.redirect(
      `${base()}/admin/seo/settings?gsc=error&gscmsg=${encodeURIComponent(
        "Google Search Console OAuth isn't configured on this server yet.",
      )}`,
    );
  }

  const state = randomBytes(24).toString("base64url");
  const authUrl = gscAuthorizeUrl(state);

  const res = NextResponse.redirect(authUrl);
  res.cookies.set({
    name: "nx_gsc_oauth_state",
    value: state,
    httpOnly: true,
    sameSite: "lax", // must survive the top-level redirect back from Google
    secure: base().startsWith("https://"),
    path: "/api/admin/integrations/google-search-console",
    maxAge: 600, // 10 minutes to complete consent
  });
  return res;
}

import { NextRequest, NextResponse } from "next/server";
import { realUser } from "@/lib/auth";
import { canAccess } from "@/lib/rbac";
import { gscExchangeCode, storeGscConnection } from "@/lib/seo/searchConsole";
import { db } from "@/lib/db";

export const dynamic = "force-dynamic";

const base = () => (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
const SETTINGS_PATH = "/admin/seo/settings";

/** Clear the one-shot OAuth state cookie on every exit path. */
function finish(res: NextResponse): NextResponse {
  res.cookies.set({
    name: "nx_gsc_oauth_state",
    value: "",
    httpOnly: true,
    path: "/api/admin/integrations/google-search-console",
    maxAge: 0,
  });
  return res;
}

/**
 * Step 2 of "Connect Google Search Console": the OAuth redirect target.
 *
 * Verifies the CSRF `state` against the httpOnly cookie, exchanges the code
 * for tokens, encrypts + stores the refresh token (+ connected account email,
 * + the resolved verified siteUrl) in `GscConnection`, then redirects back to
 * the admin settings page with a success/error indicator in the query string.
 * No token is ever logged or put in a URL.
 */
export async function GET(req: NextRequest) {
  const user = await realUser();
  if (!user || !canAccess(user.role, "platform")) {
    return finish(NextResponse.redirect(`${base()}/admin`));
  }

  const fail = (msg: string) =>
    finish(
      NextResponse.redirect(
        `${base()}${SETTINGS_PATH}?gsc=error&gscmsg=${encodeURIComponent(msg)}`,
      ),
    );

  const sp = req.nextUrl.searchParams;

  const oauthError = sp.get("error");
  if (oauthError) {
    return fail(
      oauthError === "access_denied"
        ? "Google Search Console connection cancelled."
        : `Google returned an error (${oauthError.slice(0, 60)}).`,
    );
  }

  const state = sp.get("state") ?? "";
  const stashedState = req.cookies.get("nx_gsc_oauth_state")?.value ?? "";
  if (!stashedState || !state || state !== stashedState) {
    return fail("That Google sign-in link expired or didn't match. Please try connecting again.");
  }

  const code = sp.get("code") ?? "";
  if (!code) return fail("Google didn't return an authorization code. Please try connecting again.");

  const exchanged = await gscExchangeCode(code);
  if (!exchanged.accessToken) {
    return fail(exchanged.error ?? "Couldn't complete the Google Search Console connection. Please try again.");
  }
  if (!exchanged.refreshToken) {
    // access_type=offline + prompt=consent should always yield one; if Google
    // withholds it (e.g. a prior grant wasn't revoked first) we cannot refresh
    // later, so fail loudly rather than silently storing a connection that
    // will die the moment the short-lived access token expires.
    return fail(
      "Google didn't return a refresh token. Revoke Nxeon's access at https://myaccount.google.com/permissions and try connecting again.",
    );
  }

  await storeGscConnection({ refreshToken: exchanged.refreshToken, accessToken: exchanged.accessToken });
  await db.auditLog
    .create({ data: { userId: user.id, action: "gsc.connect", detail: "OAuth authorised" } })
    .catch(() => {});

  return finish(NextResponse.redirect(`${base()}${SETTINGS_PATH}?gsc=connected`));
}

