"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { getSetting, setSetting } from "./settings";
import { getGscConnectionStatus, disconnectGsc, gscConfigured } from "./seo/searchConsole";
import { seoOpportunitySweep } from "../worker/seo";

/**
 * Admin actions for SEO Opportunity Discovery (GscConnection / SeoOpportunity).
 * Every export re-checks requireArea("platform"). Nothing here ever writes to
 * Google — only reads via the Search Console API and writes to our own DB.
 */

const OPPS_PATH = "/admin/seo";
const SETTINGS_PATH = "/admin/seo/settings";

export type SeoOpportunityStatusValue = "NEW" | "REVIEWED" | "ACTIONED" | "DISMISSED";
const STATUSES: readonly SeoOpportunityStatusValue[] = ["NEW", "REVIEWED", "ACTIONED", "DISMISSED"];

export type SeoOpportunityRow = {
  id: string;
  query: string;
  page: string | null;
  impressions: number;
  clicks: number;
  ctr: number;
  position: number;
  status: SeoOpportunityStatusValue;
  firstSeenAt: string;
  lastSeenAt: string;
};

/** The opportunity list, optionally filtered by status. Highest-impression first. */
export async function listSeoOpportunities(status?: SeoOpportunityStatusValue): Promise<SeoOpportunityRow[]> {
  await requireArea("platform");
  const where = status && STATUSES.includes(status) ? { status } : {};
  let rows;
  try {
    rows = await db.seoOpportunity.findMany({
      where,
      orderBy: [{ impressions: "desc" }, { position: "asc" }],
      take: 500,
    });
  } catch {
    // Table not migrated yet in this environment — same graceful pattern as
    // the marketing sweep's findMany guard.
    return [];
  }
  return rows.map((r) => ({
    id: r.id,
    query: r.query,
    page: r.page,
    impressions: r.impressions,
    clicks: r.clicks,
    ctr: r.ctr,
    position: r.position,
    status: r.status,
    firstSeenAt: r.firstSeenAt.toISOString(),
    lastSeenAt: r.lastSeenAt.toISOString(),
  }));
}

export type SeoOpportunityStats = {
  total: number;
  new: number;
  reviewed: number;
  actioned: number;
  dismissed: number;
};

export async function seoOpportunityStats(): Promise<SeoOpportunityStats> {
  await requireArea("platform");
  try {
    const [total, newCount, reviewed, actioned, dismissed] = await Promise.all([
      db.seoOpportunity.count(),
      db.seoOpportunity.count({ where: { status: "NEW" } }),
      db.seoOpportunity.count({ where: { status: "REVIEWED" } }),
      db.seoOpportunity.count({ where: { status: "ACTIONED" } }),
      db.seoOpportunity.count({ where: { status: "DISMISSED" } }),
    ]);
    return { total, new: newCount, reviewed, actioned, dismissed };
  } catch {
    return { total: 0, new: 0, reviewed: 0, actioned: 0, dismissed: 0 };
  }
}

export async function setSeoOpportunityStatus(
  id: string,
  status: SeoOpportunityStatusValue,
): Promise<{ ok?: boolean; error?: string }> {
  await requireArea("platform");
  if (!STATUSES.includes(status)) return { error: "Invalid status." };
  try {
    await db.seoOpportunity.update({ where: { id }, data: { status } });
  } catch {
    return { error: "Opportunity not found." };
  }
  revalidatePath(OPPS_PATH);
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Connection status + settings
// ---------------------------------------------------------------------------

export type SeoConnectionInfo = {
  configured: boolean;
  connected: boolean;
  accountEmail: string | null;
  siteUrl: string | null;
  connectedAt: string | null;
  lastSyncAt: string | null;
};

export async function getSeoConnectionInfo(): Promise<SeoConnectionInfo> {
  await requireArea("platform");
  const status = await getGscConnectionStatus();
  return {
    configured: gscConfigured(),
    connected: status.connected,
    accountEmail: status.accountEmail,
    siteUrl: status.siteUrl,
    connectedAt: status.connectedAt ? status.connectedAt.toISOString() : null,
    lastSyncAt: status.lastSyncAt ? status.lastSyncAt.toISOString() : null,
  };
}

export async function disconnectSeoConnection(): Promise<{ ok?: boolean; error?: string }> {
  await requireArea("platform");
  await disconnectGsc();
  revalidatePath(SETTINGS_PATH);
  return { ok: true };
}

export type SeoSettingsValues = {
  monitorEnabled: boolean;
  lookbackDays: string;
  minImpressions: string;
};

export async function getSeoSettings(): Promise<SeoSettingsValues> {
  await requireArea("platform");
  const [monitorEnabledRaw, lookbackDays, minImpressions] = await Promise.all([
    getSetting("seo_monitor_enabled", "true"),
    getSetting("seo_lookback_days", "90"),
    getSetting("seo_min_impressions", "15"),
  ]);
  return {
    monitorEnabled: monitorEnabledRaw === "true",
    lookbackDays,
    minImpressions,
  };
}

type ActionState = { error?: string; ok?: boolean };

export async function saveSeoSettings(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");

  const monitorEnabled = formData.get("seo_monitor_enabled") === "on" || formData.get("seo_monitor_enabled") === "true";

  const lookbackRaw = Number(formData.get("seo_lookback_days"));
  const lookbackDays = Number.isFinite(lookbackRaw) && lookbackRaw > 0 ? Math.min(Math.floor(lookbackRaw), 480) : 90;

  const minImpressionsRaw = Number(formData.get("seo_min_impressions"));
  const minImpressions =
    Number.isFinite(minImpressionsRaw) && minImpressionsRaw >= 0 ? Math.floor(minImpressionsRaw) : 15;

  await setSetting("seo_monitor_enabled", monitorEnabled ? "true" : "false");
  await setSetting("seo_lookback_days", String(lookbackDays));
  await setSetting("seo_min_impressions", String(minImpressions));

  revalidatePath(SETTINGS_PATH);
  return { ok: true };
}

/**
 * Run the sweep right now (in addition to its weekly worker tick) — lets an
 * admin verify a fresh connection immediately instead of waiting up to a week
 * for the first pull. Still fully read-only against Google; still gated by
 * requireArea. Bypasses only the worker's own pacing timer, not the
 * `seo_monitor_enabled` kill-switch (seoOpportunitySweep checks it itself).
 */
export async function runSeoSyncNow(): Promise<{ ok?: boolean; error?: string }> {
  await requireArea("platform");
  try {
    await seoOpportunitySweep();
  } catch (e) {
    return { error: e instanceof Error ? e.message : "Sync failed." };
  }
  revalidatePath(OPPS_PATH);
  revalidatePath(SETTINGS_PATH);
  return { ok: true };
}

