import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, EmptyState, timeAgo } from "@/components/ui/primitives";
import {
  listSeoOpportunities,
  seoOpportunityStats,
  getSeoConnectionInfo,
  type SeoOpportunityStatusValue,
} from "@/lib/actions-seo";
import { SeoOpportunityRowControls, SeoSyncButton } from "@/components/admin/seo/SeoOpportunitiesAdmin";

export const dynamic = "force-dynamic";

const STATUSES: readonly SeoOpportunityStatusValue[] = ["NEW", "REVIEWED", "ACTIONED", "DISMISSED"];

const statusTone: Record<string, "slate" | "brand" | "green" | "amber"> = {
  NEW: "brand",
  REVIEWED: "amber",
  ACTIONED: "green",
  DISMISSED: "slate",
};

function filterHref(status: string | undefined): string {
  return status ? `/admin/seo?status=${status}` : "/admin/seo";
}

function Pill({ active, href, children }: { active: boolean; href: string; children: React.ReactNode }) {
  return (
    <Link
      href={href}
      className={
        active
          ? "rounded-full border border-brand-500/50 bg-brand-500/15 px-3 py-1 text-xs font-medium text-brand-200"
          : "rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-xs font-medium text-slate-400 hover:text-slate-200"
      }
    >
      {children}
    </Link>
  );
}

export default async function AdminSeoPage({
  searchParams,
}: {
  searchParams: Promise<{ status?: string }>;
}) {
  await requireArea("platform");
  const sp = await searchParams;
  const status = (STATUSES as readonly string[]).includes(sp.status ?? "")
    ? (sp.status as SeoOpportunityStatusValue)
    : undefined;

  const [rows, stats, conn] = await Promise.all([
    listSeoOpportunities(status),
    seoOpportunityStats(),
    getSeoConnectionInfo(),
  ]);

  return (
    <div className="space-y-6">
      <PageHeader
        title="SEO Opportunities"
        sub="Queries where nxeon.cloud already gets real search impressions but ranks outside the top 10 — demonstrated interest, no page winning it yet. Read-only against Google Search Console; a human decides what to do with each row."
      >
        <SeoSyncButton disabled={!conn.connected} />
      </PageHeader>

      {!conn.connected && (
        <div className="card border-amber-500/30 bg-amber-500/[0.06]">
          <p className="text-sm font-semibold text-amber-200">Google Search Console isn&apos;t connected yet.</p>
          <p className="mt-1 text-xs text-slate-400">
            Connect it on the{" "}
            <Link href="/admin/seo/settings" className="text-brand-300 underline">
              Settings
            </Link>{" "}
            tab to start pulling opportunities.
          </p>
        </div>
      )}

      <div className="grid grid-cols-2 gap-3 sm:grid-cols-5">
        <Stat label="Total" value={stats.total} />
        <Stat label="New" value={stats.new} />
        <Stat label="Reviewed" value={stats.reviewed} />
        <Stat label="Actioned" value={stats.actioned} />
        <Stat label="Dismissed" value={stats.dismissed} />
      </div>

      <div className="flex flex-wrap gap-2">
        <Pill active={!status} href={filterHref(undefined)}>
          All
        </Pill>
        {STATUSES.map((s) => (
          <Pill key={s} active={status === s} href={filterHref(s)}>
            {s.charAt(0) + s.slice(1).toLowerCase()}
          </Pill>
        ))}
      </div>

      {rows.length === 0 ? (
        <EmptyState
          title="No opportunities yet"
          sub={
            conn.connected
              ? "The weekly sweep hasn't found a striking-distance query yet, or hasn't run yet — try Sync now above."
              : "Connect Google Search Console on the Settings tab, then run a sync."
          }
        />
      ) : (
        <div className="card overflow-x-auto p-0">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-white/10 text-left text-[11px] uppercase tracking-wide text-slate-500">
                <th className="px-4 py-3 font-medium">Query</th>
                <th className="px-4 py-3 font-medium">Page</th>
                <th className="px-4 py-3 font-medium text-right">Impressions</th>
                <th className="px-4 py-3 font-medium text-right">Clicks</th>
                <th className="px-4 py-3 font-medium text-right">CTR</th>
                <th className="px-4 py-3 font-medium text-right">Position</th>
                <th className="px-4 py-3 font-medium">Status</th>
                <th className="px-4 py-3 font-medium">Last seen</th>
                <th className="px-4 py-3 font-medium text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => (
                <tr key={r.id} className="border-b border-white/5 last:border-0">
                  <td className="max-w-xs truncate px-4 py-3 text-slate-200" title={r.query}>
                    {r.query}
                  </td>
                  <td className="max-w-xs truncate px-4 py-3 text-slate-400" title={r.page ?? ""}>
                    {r.page ? (
                      <a href={r.page} target="_blank" rel="noreferrer" className="hover:text-brand-300 hover:underline">
                        {r.page.replace(/^https?:\/\//, "")}
                      </a>
                    ) : (
                      <span className="text-slate-600">—</span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-right tabular-nums text-slate-200">{r.impressions.toLocaleString()}</td>
                  <td className="px-4 py-3 text-right tabular-nums text-slate-400">{r.clicks.toLocaleString()}</td>
                  <td className="px-4 py-3 text-right tabular-nums text-slate-400">{(r.ctr * 100).toFixed(1)}%</td>
                  <td className="px-4 py-3 text-right tabular-nums text-slate-200">{r.position.toFixed(1)}</td>
                  <td className="px-4 py-3">
                    <Badge tone={statusTone[r.status] ?? "slate"}>{r.status.toLowerCase()}</Badge>
                  </td>
                  <td className="px-4 py-3 whitespace-nowrap text-xs text-slate-500">{timeAgo(new Date(r.lastSeenAt))}</td>
                  <td className="px-4 py-3">
                    <SeoOpportunityRowControls id={r.id} status={r.status} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function Stat({ label, value }: { label: string; value: number }) {
  return (
    <div className="card py-3">
      <div className="text-2xl font-semibold text-white">{value}</div>
      <div className="text-[11px] uppercase tracking-wide text-slate-500">{label}</div>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { setSeoOpportunityStatus, runSeoSyncNow, type SeoOpportunityStatusValue } from "@/lib/actions-seo";

const STATUSES: readonly SeoOpportunityStatusValue[] = ["NEW", "REVIEWED", "ACTIONED", "DISMISSED"];

/** Per-row status dropdown, saves on change. */
export function SeoOpportunityRowControls({ id, status }: { id: string; status: SeoOpportunityStatusValue }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [value, setValue] = useState(status);
  const [err, setErr] = useState<string | null>(null);

  return (
    <div className="flex items-center justify-end gap-2">
      {err && <span className="text-xs text-red-400">{err}</span>}
      <select
        className="input py-1 text-xs"
        value={value}
        disabled={pending}
        onChange={(e) => {
          const next = e.target.value as SeoOpportunityStatusValue;
          setValue(next);
          setErr(null);
          start(async () => {
            const res = await setSeoOpportunityStatus(id, next);
            if (res.error) {
              setErr(res.error);
              setValue(status);
              return;
            }
            router.refresh();
          });
        }}
      >
        {STATUSES.map((s) => (
          <option key={s} value={s}>
            {s.charAt(0) + s.slice(1).toLowerCase()}
          </option>
        ))}
      </select>
    </div>
  );
}

/** "Sync now" — runs the sweep immediately instead of waiting for the weekly tick. */
export function SeoSyncButton({ disabled }: { disabled?: boolean }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);

  return (
    <div className="flex items-center gap-2">
      {msg && <span className="text-xs text-slate-400">{msg}</span>}
      <button
        className="btn-secondary px-3 py-1.5 text-xs"
        disabled={disabled || pending}
        title={disabled ? "Connect Google Search Console first" : undefined}
        onClick={() =>
          start(async () => {
            setMsg(null);
            const res = await runSeoSyncNow();
            setMsg(res.error ?? "Synced.");
            router.refresh();
          })
        }
      >
        {pending ? "Syncing…" : "Sync now"}
      </button>
    </div>
  );
}

import { requireArea } from "@/lib/rbac";
import { PageHeader } from "@/components/ui/primitives";
import { getSeoConnectionInfo, getSeoSettings } from "@/lib/actions-seo";
import { SeoConnectionCard, SeoSettingsForm } from "@/components/admin/seo/SeoSettingsAdmin";

export const dynamic = "force-dynamic";

export default async function AdminSeoSettingsPage({
  searchParams,
}: {
  searchParams: Promise<{ gsc?: string; gscmsg?: string }>;
}) {
  await requireArea("platform");
  const sp = await searchParams;
  const [conn, settings] = await Promise.all([getSeoConnectionInfo(), getSeoSettings()]);

  return (
    <div className="space-y-6">
      <PageHeader
        title="SEO Settings"
        sub="Connect Google Search Console (read-only) and tune the thresholds the weekly opportunity sweep uses."
      />

      {sp.gsc === "connected" && (
        <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
          Google Search Console connected.
        </div>
      )}
      {sp.gsc === "error" && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {sp.gscmsg || "Couldn't connect Google Search Console."}
        </div>
      )}

      <div className="card">
        <p className="section-label mb-4">Connection</p>
        <SeoConnectionCard conn={conn} />
      </div>

      <div className="card">
        <p className="section-label mb-4">Opportunity thresholds</p>
        <SeoSettingsForm settings={settings} />
      </div>
    </div>
  );
}

"use client";

import { useActionState, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { disconnectSeoConnection, saveSeoSettings, type SeoConnectionInfo, type SeoSettingsValues } from "@/lib/actions-seo";

type ActionState = { error?: string; ok?: boolean };
const EMPTY: ActionState = {};

export function SeoConnectionCard({ conn }: { conn: SeoConnectionInfo }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [confirming, setConfirming] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  if (!conn.configured) {
    return (
      <p className="text-sm text-slate-400">
        Google Search Console OAuth isn&apos;t configured on this server yet — set{" "}
        <code className="text-slate-300">GSC_OAUTH_CLIENT_ID</code>, <code className="text-slate-300">GSC_OAUTH_CLIENT_SECRET</code> and{" "}
        <code className="text-slate-300">GSC_OAUTH_REDIRECT_URI</code> in the environment.
      </p>
    );
  }

  if (!conn.connected) {
    return (
      <div className="space-y-3">
        <p className="text-sm text-slate-400">
          Not connected. Connecting grants read-only access (Search Console&apos;s <code>webmasters.readonly</code> scope) —
          Nxeon never writes anything back to Google.
        </p>
        <a href="/api/admin/integrations/google-search-console/connect" className="btn-primary inline-flex px-4 py-2 text-sm">
          Connect Google Search Console
        </a>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {err && <p className="text-sm text-red-400">{err}</p>}
      <div className="flex flex-wrap items-center gap-2 text-sm text-slate-300">
        <span className="inline-flex items-center gap-2">
          <span className="h-2 w-2 rounded-full bg-emerald-400" />
          Connected as <strong className="text-white">{conn.accountEmail ?? "unknown account"}</strong>
        </span>
      </div>
      <dl className="grid gap-x-8 gap-y-1 text-xs text-slate-500 sm:grid-cols-2">
        <div>
          <dt className="inline">Property: </dt>
          <dd className="inline text-slate-400">{conn.siteUrl || "not yet resolved"}</dd>
        </div>
        <div>
          <dt className="inline">Connected: </dt>
          <dd className="inline text-slate-400">{conn.connectedAt ? new Date(conn.connectedAt).toLocaleString() : "—"}</dd>
        </div>
        <div>
          <dt className="inline">Last synced: </dt>
          <dd className="inline text-slate-400">{conn.lastSyncAt ? new Date(conn.lastSyncAt).toLocaleString() : "never yet"}</dd>
        </div>
      </dl>
      <div className="flex justify-end gap-2 pt-1">
        {confirming ? (
          <>
            <button
              className="btn-danger px-3 py-1.5 text-xs"
              disabled={pending}
              onClick={() =>
                start(async () => {
                  const res = await disconnectSeoConnection();
                  if (res.error) {
                    setErr(res.error);
                    return;
                  }
                  setConfirming(false);
                  router.refresh();
                })
              }
            >
              {pending ? "Disconnecting…" : "Confirm disconnect"}
            </button>
            <button className="btn-ghost px-2 py-1.5 text-xs" onClick={() => setConfirming(false)} disabled={pending}>
              Cancel
            </button>
          </>
        ) : (
          <button className="btn-danger px-3 py-1.5 text-xs" onClick={() => setConfirming(true)}>
            Disconnect
          </button>
        )}
      </div>
    </div>
  );
}

export function SeoSettingsForm({ settings }: { settings: SeoSettingsValues }) {
  const [state, action, pending] = useActionState(saveSeoSettings, EMPTY);

  return (
    <form action={action} className="space-y-4">
      {state?.error && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{state.error}</div>
      )}
      {state?.ok && (
        <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">Saved.</div>
      )}
      <label className="flex items-center gap-2 text-sm text-slate-300">
        <input type="checkbox" name="seo_monitor_enabled" defaultChecked={settings.monitorEnabled} />
        Weekly sweep enabled
      </label>
      <div className="grid gap-4 sm:grid-cols-2">
        <div>
          <label className="label">Lookback window (days)</label>
          <input
            className="input"
            type="number"
            name="seo_lookback_days"
            min={7}
            max={480}
            defaultValue={settings.lookbackDays}
          />
          <p className="mt-1 text-xs text-slate-500">How far back each sweep pulls Search Console data. 90 is Google&apos;s usual practical max for daily-granularity data.</p>
        </div>
        <div>
          <label className="label">Minimum impressions</label>
          <input
            className="input"
            type="number"
            name="seo_min_impressions"
            min={0}
            defaultValue={settings.minImpressions}
          />
          <p className="mt-1 text-xs text-slate-500">Queries below this impression count over the lookback window are skipped — keeps the list to real demonstrated interest.</p>
        </div>
      </div>
      <p className="text-xs text-slate-500">
        Ranking band is fixed at positions 11–30 (outside the top 10, but close enough to be a realistic content-gap
        target) — a human still judges each row; this only bounds the raw list.
      </p>
      <div className="flex justify-end">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Save settings"}
        </button>
      </div>
    </form>
  );
}

